    public const int kNumFunctions = (int)RuntimeFunctionId.NumFunctions;

    /// <summary>Runtime::FunctionForId(id)-&gt;name: the C++ name, with a leading '_' for inline intrinsics.</summary>
    public static string Name(RuntimeFunctionId id) => s_names[(int)id];
    public static int NumberOfArguments(RuntimeFunctionId id) => s_nargs[(int)id];
    public static int ResultSize(RuntimeFunctionId id) => s_resultSizes[(int)id];
    public static bool IsInline(RuntimeFunctionId id) => s_names[(int)id].StartsWith('_');

    static Dictionary<string, RuntimeFunctionId>? s_byName;

    /// <summary>Looks a function up by its Runtime::Function name (e.g. "DefineClass", "_CreateJSGeneratorObject").</summary>
    public static bool TryFromName(string name, out RuntimeFunctionId id)
    {
        var map = s_byName;
        if (map is null)
        {
            map = new Dictionary<string, RuntimeFunctionId>(s_names.Length, StringComparer.Ordinal);
            for (int i = 0; i < s_names.Length; i++) map[s_names[i]] = (RuntimeFunctionId)i;
            s_byName = map;
        }
        return map.TryGetValue(name, out id);
    }
